return [
  {
    json: {
      candidate_name: parentData.candidate_name,
      candidate_email: parentData.candidate_email,
      subject: "Nexium AI - Your Personalized Interview Preparation Deck",
      report_body: html,
      action_path: parentData.action_path
    }
  }
];
